    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xC6263141EDC1A0F3ULL + 0xDF5C6DC11B7E5E27ULL);
