            aOrbiterE = ((aWandererD + RotL64(aScatter, 53U)) + 0xB2521CBAEE5FBE1BULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterH = ((aWandererK + RotL64(aIngress, 27U)) + 0xE20C1152205C6EFEULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterB = (aWandererC + RotL64(aPrevious, 43U)) + 0x47825F83F35BAED5ULL;
            aOrbiterC = (aWandererG + RotL64(aCross, 34U)) + 0xA0CE16CD6AE27C77ULL;
            aOrbiterI = ((aWandererA + RotL64(aScatter, 57U)) + RotL64(aCarry, 3U)) + 0xBC81620956D8669AULL;
            aOrbiterG = ((aWandererH + RotL64(aCross, 39U)) + RotL64(aCarry, 27U)) + 0x08F45DF166AB03EFULL;
