            aOrbiterA = RotL64((aOrbiterA * 0x1CB70DBD54C134B7ULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x558E9C36E5CA5327ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0xEA3E4E0B7E30B04EULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 18U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x198B7A057A4BBB93ULL), 19U);
            //
