            aOrbiterC = (aWandererC + RotL64(aCross, 4U)) + 0x545E31EBC749F1C5ULL;
            aOrbiterE = (aWandererI + RotL64(aScatter, 57U)) + 0xE481B73F6997B9EDULL;
            aOrbiterF = ((aWandererA + RotL64(aCross, 37U)) + RotL64(aCarry, 57U)) + 0x8188E0B701E40583ULL;
            aOrbiterK = (((aWandererG + RotL64(aPrevious, 29U)) + RotL64(aCarry, 27U)) + 0x207E8DE2F2BB2756ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 11U)) & S_SALT1];
