            aOrbiterC = (aOrbiterC + aOrbiterA) + 0xB4ADCA1CF0737434ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0xC9C3A2A8CB29DF7EULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 15U)) & S_SALT1];
