            //
            aOrbiterG = ((aOrbiterG + aOrbiterD) + 0x77783782F23873EBULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0xF4A784C9E2B5D14EULL;
