            aWandererD = aWandererD + ((RotL64(aIngress, 27U) + RotL64(aOrbiterG, 43U)) + aOrbiterH);
            aWandererJ = aWandererJ ^ (((RotL64(aCross, 41U) + aOrbiterG) + RotL64(aOrbiterA, 14U)) + aKeyRotateAWandererUpdateSaltB[((aIndex + 13U)) & S_SALT1]);
