            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0xF2C4B943E0292A3BULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x9D5EBE374145DAE7ULL), 35U);
