            //
            aOrbiterE = ((aWandererJ + RotL64(aScatter, 47U)) + RotL64(aCarry, 19U)) + 0xE51E20F0C1D7F308ULL;
            aOrbiterF = (((aWandererE + RotL64(aCross, 23U)) + RotL64(aCarry, 57U)) + 0xE543189E904967CCULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterK = (aWandererC + RotL64(aPrevious, 35U)) + 0x5D6CF1A9B43FA0A7ULL;
            aOrbiterA = ((aWandererA + RotL64(aIngress, 29U)) + RotL64(aCarry, 43U)) + 0x96CFC55A45435CA5ULL;
            aOrbiterI = ((aWandererD + RotL64(aScatter, 57U)) + 0xBCBC2E2CC11CE8C5ULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 25U)) & S_SALT1];
            aOrbiterG = (aWandererG + RotL64(aPrevious, 4U)) + 0x66B127E63F64A775ULL;
            aOrbiterC = (aWandererH + RotL64(aIngress, 11U)) + 0x260AB5183250F651ULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x454FE605E49EA330ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x19A895EFC56BE170ULL;
