            //
            aOrbiterK = ((aOrbiterK + aOrbiterA) + 0x8F924D933203DECBULL) + aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xF7E71060AB50708EULL;
            aOrbiterI = RotL64((aOrbiterI * 0xEB633CF18F4DBDF5ULL), 13U);
