            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0xB9A58E51918AB979ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0x423053DF679C167DULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xF8F901379E0606A3ULL), 43U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x2E696CB5A8B7152DULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0xA31DEBE5F35AA54DULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 8U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xC043779E386BF4D7ULL), 5U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x81915D5547E03CBAULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0xAF1478E297688711ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x1144E48233D191EFULL), 23U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x6A5A3B968BE2FC18ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0xDEF81F8D1E5DDE26ULL;
