            aWandererJ = aWandererJ ^ (((RotL64(aIngress, 19U) + aOrbiterE) + RotL64(aOrbiterG, 27U)) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 15U)) & S_SALT1]);
