        //
        // Ingress:
        //      aFuseLaneC (-->), aFuseLaneA (-->), aKeyRowReadB (-->), aPoisonLaneB (<-?->)
        //
        // Cross:
        //      aFuseLaneB (<--), aMagmaLaneB (<--), aKeyRowReadA (<--), aPoisonLaneA (<-?->)
