            //
            aIngress = (RotL64(aFuseLaneC[((aIndex + 28089U)) & S_BLOCK1], 51U) ^ RotL64(aFuseLaneA[((aIndex + 27000U)) & S_BLOCK1], 21U));
            aIngress ^= (RotL64(aKeyRowReadB[((aIndex + 29461U)) & W_KEY1], 13U) ^ RotL64(aPoisonLaneB[((aIndex + 31294U)) & S_BLOCK1], 40U));
