            aCross ^= (RotL64(aKeyRowReadA[(((2047U - aIndex) + 31812U)) & W_KEY1], 60U) ^ RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 32409U)) & S_BLOCK1], 39U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
