            aScatter = (RotL64(aPrevious, 19U) ^ RotL64(aCarry, 3U)) ^ (RotL64(aIngress, 52U) + RotL64(aCross, 37U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = (aWandererA + RotL64(aCross, 47U)) + 0x86E317D8DEA31130ULL;
            aOrbiterJ = (aWandererC + RotL64(aScatter, 21U)) + 0x50B716EA5FA13B8DULL;
            aOrbiterB = (((aWandererD + RotL64(aPrevious, 35U)) + RotL64(aCarry, 35U)) + 0x9B6794696234ECBCULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterK = (aWandererH + RotL64(aIngress, 56U)) + 0xEB3D7A9850857A3CULL;
            aOrbiterF = (((aWandererI + RotL64(aScatter, 13U)) + RotL64(aCarry, 47U)) + 0xC46EEF81E2DCFD7BULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterE = ((aWandererJ + RotL64(aCross, 5U)) + RotL64(aCarry, 11U)) + 0x2A585214507AE16DULL;
            aOrbiterH = (aWandererF + RotL64(aIngress, 41U)) + 0xC628A06E71341D8AULL;
            //
            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0x70146EEB27986751ULL) + aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x81533523D6945E9BULL;
            aOrbiterB = RotL64((aOrbiterB * 0x7E18D6EDAAD7DA13ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x4AE8A5A1D055C3E6ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x03654193D37D69F1ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x463B054982A94FD3ULL), 47U);
