            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x71DBCED5770FDAEAULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterF) ^ 0x6885D89B99773EF3ULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x1811C2027B4A3A6BULL), 11U);
