            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x70A670C60A21A20EULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterB) ^ 0xF8B288F0E1A187A4ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 27U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x8AA534270887DC1DULL), 3U);
