            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0x8B2434D12063968FULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 26U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xE05A815A8290CC76ULL;
