            aWandererA = aWandererA ^ ((RotL64(aCross, 60U) + aOrbiterG) + RotL64(aOrbiterE, 43U));
            aWandererJ = aWandererJ + ((((RotL64(aIngress, 43U) + RotL64(aOrbiterF, 35U)) + aOrbiterB) + RotL64(aCarry, 35U)) + aKeyRotateAWandererUpdateSaltD[((aIndex + 25U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aScatter, 21U) + RotL64(aOrbiterG, 60U)) + aOrbiterB) + aKeyRotateAWandererUpdateSaltE[(((31U - aIndex) + 3U)) & S_SALT1]);
            aWandererC = aWandererC + ((RotL64(aPrevious, 13U) + RotL64(aOrbiterK, 11U)) + aOrbiterG);
            aWandererD = aWandererD ^ ((RotL64(aIngress, 35U) + aOrbiterG) + RotL64(aOrbiterJ, 29U));
